& \\
\text{i.e. } \sigma([\underline{u},\varepsilon_0]) = \sigma(\underline{u}) \rho(\underline{u})^{-1}
&
\begin{cases} \rho(\underline{u}^{-1}) = \underline{u}^{-1} \xi^{-1} \\ \rho(\underline{u}) = \xi \underline{u} \\ \sigma(\underline{u}) = \eta \underline{u} \end{cases}
\end{array}
